css:
.uv-tp {
  --c1: #0071e3;
  --c2: #8ec5ff;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uv-tp {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  font-weight: 600;
  line-height: 1;
  padding: 1em 2em;
  border: 0;
  border-radius: 999px;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  position: relative;
  color: #fff;
  background: var(--c1);
}

.uv-tp span {
  position: absolute;
  left: 50%;
  bottom: calc(100% + .7em);
  padding: .6em .9em;
  border-radius: .7em;
  font-size: .8em;
  font-weight: 500;
  white-space: nowrap;
  color: var(--bg);
  background: var(--fg);
  box-shadow: 0 10px 30px -10px rgba(0,0,0,.4);
  transform: translateX(-50%) scale(.4);
  transform-origin: bottom center;
  opacity: 0;
  pointer-events: none;
  transition: transform calc(0.4s / var(--k)) cubic-bezier(.34,1.56,.64,1),opacity calc(0.2s / var(--k));
}

.uv-tp span::after {
  content: "";
  position: absolute;
  left: 50%;
  top: 100%;
  border: .4em solid transparent;
  border-top-color: var(--fg);
  translate: -50% 0;
}

.uv-tp:hover span,.uv-tp:focus-visible span {
  transform: translateX(-50%) scale(1);
  opacity: 1;
}

