// @ts-nocheck: setup() es JavaScript del DOM sin tipos, el mismo de la pestaña JS.
import { useEffect, useRef, type CSSProperties } from "react";

const css = `
.uv-tf {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  position: relative;
  display: grid;
  place-items: center;
  width: 16em;
  height: 9em;
  border-radius: 1.2em;
  font-size: var(--s);
  color: color-mix(in srgb,var(--fg) 55%,transparent);
  background: color-mix(in srgb,var(--fg) 5%,transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb,var(--fg) 10%,transparent);
  cursor: crosshair;
}

.uv-tf span {
  position: absolute;
  left: var(--x,50%);
  top: var(--y,50%);
  padding: .45em .8em;
  border-radius: 999px;
  font-size: .75em;
  font-weight: 600;
  white-space: nowrap;
  color: #fff;
  background: var(--c1);
  box-shadow: 0 8px 20px -8px var(--c1);
  transform: translate(-50%,-160%) scale(.6);
  opacity: 0;
  pointer-events: none;
  transition: transform calc(0.3s / var(--k)) cubic-bezier(.34,1.56,.64,1),opacity calc(0.2s / var(--k)),left .08s linear,top .08s linear;
}

.uv-tf:hover span {
  transform: translate(-50%,-160%) scale(1);
  opacity: 1;
}
`;

// Interacción en JavaScript del DOM: la misma que en la pestaña JS.
// eslint-disable-next-line @typescript-eslint/no-explicit-any
function setup(el: any) {
  el.addEventListener("pointermove",e=>{const r=el.getBoundingClientRect();el.style.setProperty("--x",e.clientX-r.left+"px");el.style.setProperty("--y",e.clientY-r.top+"px")})
}

export default function TipFollow() {
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const el = ref.current?.firstElementChild;
    return el ? setup(el) : undefined;
  }, []);

  return (
    <>
      <style>{css}</style>
      <div
        ref={ref} style={{
          "--c1": "#0071e3",
          "--c2": "#8ec5ff",
          "--s": "16px",
          "--k": "1",
          "--fg": "#1d1d1f",
          "--bg": "#f5f5f7",
        } as CSSProperties}
      >
        <div className="uv-tf">Mueve el ratón por aquí<span>Estás aquí</span></div>
      </div>
    </>
  );
}

