css:
.uv-tgl {
  --c1: #0f766e;
  --c2: #ccfbf1;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uv-tgl {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  max-width: 18em;
  margin: 0;
  font-size: calc(var(--s) * 1.05);
  line-height: 1.6;
}

.uv-tgl .tm {
  position: relative;
  font-weight: 650;
  color: var(--c1);
  text-decoration: underline dotted;
  text-decoration-thickness: 2px;
  text-underline-offset: .25em;
  cursor: help;
  outline: 0;
  border-radius: .2em;
}

.uv-tgl .tm:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uv-tgl .df {
  position: absolute;
  left: 50%;
  bottom: calc(100% + .7em);
  z-index: 5;
  display: block;
  width: 15em;
  padding: .85em 1em;
  border-radius: .9em;
  font-size: .82em;
  font-weight: 400;
  line-height: 1.45;
  text-align: left;
  color: var(--bg);
  background: var(--fg);
  box-shadow: 0 .8em 1.6em -.6em rgba(0,0,0,.45);
  transform: translate(-50%,.4em) scale(.96);
  transform-origin: 50% 100%;
  opacity: 0;
  visibility: hidden;
  transition: all calc(0.22s / var(--k)) cubic-bezier(.25,.1,.25,1);
  pointer-events: none;
}

.uv-tgl .df b {
  display: block;
  margin-bottom: .2em;
  color: var(--c2);
}

.uv-tgl .df b::first-letter {
  text-transform: uppercase;
}

.uv-tgl .df::after {
  content: "";
  position: absolute;
  left: 50%;
  top: 100%;
  width: .7em;
  height: .7em;
  background: var(--fg);
  transform: translate(-50%,-55%) rotate(45deg);
  border-radius: 0 0 .15em 0;
}

.uv-tgl .tm:hover .df,.uv-tgl .tm:focus .df {
  transform: translate(-50%,0) scale(1);
  opacity: 1;
  visibility: visible;
  transition-delay: calc(0.12s / var(--k));
}

