  height: 1.2em;
}

.uv-tuf button:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uv-tuf .tt {
  position: absolute;
  left: 50%;
  bottom: calc(100% + .8em);
