.uv-tuf .tt .p2 {
  order: -1;
}

.uv-tuf:hover .p1,.uv-tuf:focus-within .p1 {
  transform: none;
  filter: none;
  transition-delay: 0s;
}

.uv-tuf:hover .p2,.uv-tuf:focus-within .p2 {
  transform: none;
  filter: none;
  transition-delay: calc(0.2s / var(--k));
}

