css:
.uvq08-wch {
  --c1: #ff9f0a;
  --c2: #30d158;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq08-wch {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  padding: 1em;
}

.uvq08-wch .fc {
  position: relative;
  width: 13em;
  height: 13em;
  border-radius: 50%;
  background: radial-gradient(circle at 50% 40%,#17171a,#000 70%);
  box-shadow: 0 0 0 .5em #2c2c30,0 0 0 .58em #77777d,0 1.4em 2.2em -.6em rgba(0,0,0,.6);
}

.uvq08-wch .fc::after {
  content: "";
  position: absolute;
  right: -.95em;
  top: 50%;
  width: .5em;
  height: 1.6em;
  translate: 0 -50%;
  border-radius: .2em;
  background: linear-gradient(90deg,#55555b,#2c2c30);
}

.uvq08-wch svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: visible;
}

.uvq08-wch .tk line {
  stroke: #4a4a4f;
  stroke-width: 1;
}

.uvq08-wch .tk .mj {
  stroke: #c7c7cc;
  stroke-width: 1.6;
}

.uvq08-wch .sd {
  fill: var(--c1);
  transform-origin: 100px 100px;
  animation: uvq08-wch-s 60s linear infinite;
}

.uvq08-wch .tm {
  fill: #f5f5f7;
  font: 600 30px/1 system-ui,-apple-system,sans-serif;
  letter-spacing: -.5px;
}

.uvq08-wch .ct {
  fill: var(--c1);
  font: 700 10.5px/1 system-ui,-apple-system,sans-serif;
  letter-spacing: 4px;
  opacity: 0;
  transition: opacity calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1),letter-spacing calc(0.5s / var(--k)) cubic-bezier(.22,1,.36,1);
}

.uvq08-wch .c0,.uvq08-wch .c3 {
  fill: var(--c2);
}

.uvq08-wch .k {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  position: absolute;
  display: grid;
  place-items: center;
  width: 2.9em;
  height: 2.9em;
  translate: -50% -50%;
  border-radius: 50%;
  font-size: .95em;
  font-weight: 700;
  color: #f5f5f7;
  background: radial-gradient(closest-side,#1c1c1e calc(100% - .24em),transparent calc(100% - .22em)),conic-gradient(var(--r) calc(var(--p) * 1%),#2e2e31 0);
  transition: transform calc(0.3s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uvq08-wch .k0 {
  left: 32.3%;
  top: 32.3%;
}

.uvq08-wch .k1 {
  left: 67.7%;
  top: 32.3%;
}

.uvq08-wch .k2 {
  left: 67.7%;
  top: 67.7%;
}

.uvq08-wch .k3 {
  left: 32.3%;
  top: 67.7%;
}

.uvq08-wch .k:hover {
  transform: scale(1.08);
}

.uvq08-wch .k:active {
  transform: scale(.94);
}

.uvq08-wch .k:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uvq08-wch:has(.k0:is(:hover,:focus-visible,.pk)) .c0,.uvq08-wch:has(.k1:is(:hover,:focus-visible,.pk)) .c1,.uvq08-wch:has(.k2:is(:hover,:focus-visible,.pk)) .c2,.uvq08-wch:has(.k3:is(:hover,:focus-visible,.pk)) .c3 {
  opacity: 1;
  letter-spacing: .6px;
}

@keyframes uvq08-wch-s {
  to {
    transform: rotate(360deg);
  }
}

@media (prefers-reduced-motion:reduce) {
  .uvq08-wch,.uvq08-wch *,.uvq08-wch *::before,.uvq08-wch *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

