css:
.uvq08-tag {
  --c1: #4f7c6b;
  --c2: #b07d4f;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq08-tag {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
}

.uvq08-tag .sc {
  position: relative;
  width: 15em;
  height: 15.6em;
}

.uvq08-tag .mg {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  position: absolute;
  left: 50%;
  top: 2em;
  width: 4em;
  height: 4.4em;
  translate: -50% 0;
  border-radius: .35em .35em 1.2em 1.2em;
  background: radial-gradient(circle at 30% 25%,rgba(255,255,255,.35),transparent 40%),radial-gradient(rgba(0,0,0,.18) 1px,transparent 1.5px) 0 0/.55em .55em,linear-gradient(90deg,color-mix(in srgb,var(--c1) 75%,#000),var(--c1) 35%,color-mix(in srgb,var(--c1) 80%,#fff) 55%,color-mix(in srgb,var(--c1) 70%,#000));
  box-shadow: inset 0 .3em 0 rgba(255,255,255,.18),0 .3em .4em -.1em rgba(0,0,0,.35);
  transition: transform calc(0.35s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uvq08-tag .hl {
  position: absolute;
  right: -1.2em;
  top: .8em;
  width: 1.5em;
  height: 2.2em;
  border: .45em solid color-mix(in srgb,var(--c1) 80%,#000);
  border-left: 0;
  border-radius: 0 1.1em 1.1em 0;
}

.uvq08-tag .st,.uvq08-tag .st::before {
  position: absolute;
  left: 50%;
  top: -1.9em;
  width: .25em;
  height: 1.4em;
  border-radius: 1em;
  background: linear-gradient(transparent,color-mix(in srgb,var(--fg) 22%,transparent),transparent);
  animation: uvq08-tag-s calc(2.4s / var(--k)) cubic-bezier(.25,.1,.25,1) infinite;
}

.uvq08-tag .st::before {
  content: "";
  left: -.8em;
  top: .3em;
  animation-delay: calc(-1.2s / var(--k));
}

.uvq08-tag .mg:hover {
  transform: translateY(-.15em);
}

.uvq08-tag .mg:active {
  transform: scale(.95);
}

.uvq08-tag .mg:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
  outline-offset: 5px;
}

.uvq08-tag .sh {
  position: absolute;
  left: 0;
  right: 0;
  top: 6.4em;
  height: .9em;
  border-radius: .2em;
  background: repeating-linear-gradient(90deg,rgba(0,0,0,.06) 0 2px,transparent 2px 9px),linear-gradient(180deg,color-mix(in srgb,var(--c2) 75%,#fff),var(--c2) 40%,color-mix(in srgb,var(--c2) 70%,#000));
  box-shadow: 0 .6em .8em -.4em rgba(0,0,0,.45);
}

.uvq08-tag .hk {
  position: absolute;
  left: 50%;
  top: 7.15em;
  width: .8em;
  height: .8em;
  translate: -50% 0;
  border: .16em solid #b08d57;
  border-top-color: transparent;
  border-radius: 50%;
}

.uvq08-tag .sw {
  position: absolute;
  left: 50%;
  top: 7.85em;
  width: 0;
  rotate: var(--r,0deg);
  transform-origin: 0 0;
  translate: 0 -.8em;
  opacity: 0;
  visibility: hidden;
  filter: drop-shadow(0 .4em .35em rgba(0,0,0,.25));
  transition: translate calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1),opacity calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1),visibility 0s calc(0.3s / var(--k));
}

.uvq08-tag .str {
  position: absolute;
  left: -.75px;
  top: -.2em;
  width: 1.5px;
  height: 1.95em;
  background: #7a5a3a;
}

.uvq08-tag .tg {
  position: absolute;
  left: 50%;
  top: 1.5em;
  display: grid;
  justify-items: center;
  width: 6.2em;
  padding: 1.4em .5em .8em;
  translate: -50% 0;
  text-align: center;
  color: #2b1d0e;
  background: repeating-linear-gradient(35deg,rgba(0,0,0,.03) 0 2px,transparent 2px 5px),linear-gradient(180deg,#dcc09a,#c9a77c);
  clip-path: polygon(22% 0,78% 0,100% 16%,100% 100%,0 100%,0 16%);
  -webkit-mask: radial-gradient(circle at 50% .65em,transparent .22em,#000 .24em);
  mask: radial-gradient(circle at 50% .65em,transparent .22em,#000 .24em);
}

.uvq08-tag .tg::before {
  content: "";
  position: absolute;
  left: 50%;
  top: .65em;
  width: .8em;
  height: .8em;
  translate: -50% -50%;
  border-radius: 50%;
  box-shadow: inset 0 0 0 .14em #c9a86a;
}

.uvq08-tag .nm {
  font-size: .62em;
  font-weight: 700;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: #5a3e22;
}

.uvq08-tag .tg b {
  font: 700 1.6em/1.15 Georgia,"Times New Roman",serif;
}

.uvq08-tag .ds {
  font-size: .58em;
  line-height: 1.3;
  color: #5a3e22;
}

.uvq08-tag:has(.mg:is(:hover,:focus-visible)) .sw,.uvq08-tag.pk .sw {
  translate: 0 0;
  opacity: 1;
  visibility: visible;
  transition: translate calc(0.4s / var(--k)) cubic-bezier(.34,1.56,.64,1),opacity calc(0.15s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

@keyframes uvq08-tag-s {
  0% {
    transform: translateY(.4em) scaleY(.6);
    opacity: 0;
  }
  40% {
    opacity: 1;
  }
  100% {
    transform: translateY(-.6em) scaleY(1);
    opacity: 0;
  }
}

@media (prefers-reduced-motion:reduce) {
  .uvq08-tag,.uvq08-tag *,.uvq08-tag *::before,.uvq08-tag *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

