const kick=f=>{if(rm.matches)return;v+=f;if(!raf)raf=requestAnimationFrame(tick)};
mg.addEventListener("pointerenter",()=>kick(-3.5));mg.addEventListener("focus",()=>kick(-3.5));el.addEventListener("pointermove",e=>kick(Math.max(-1.2,Math.min(1.2,e.movementX*0.06))));kick(-3.5);
return()=>cancelAnimationFrame(raf)
});

