.uvq08-kbd {
  --c1: #0a84ff;
  --c2: #8e8e93;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq08-kbd {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  display: grid;
  gap: .7em;
  padding-top: 1.2em;
}

.uvq08-kbd .fd {
  display: flex;
  align-items: center;
  min-height: 2.4em;
  padding: 0 1em;
  border-radius: 1.2em;
  font-size: .95em;
  color: #fff;
  background: #1c1c1e;
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.08);
}

.uvq08-kbd .tx {
  white-space: pre;
}

.uvq08-kbd .cr {
  width: 2px;
  height: 1.2em;
  margin-left: 1px;
  border-radius: 1px;
  background: var(--c1);
  animation: uvq08-kbd-c 1s steps(1,end) infinite;
}

.uvq08-kbd .kb {
  display: grid;
  gap: .5em;
  padding: .6em .35em .7em;
  border-radius: .9em;
  background: #2c2c2e;
  box-shadow: 0 1.2em 2em -1.2em rgba(0,0,0,.6);
}

.uvq08-kbd .rw {
  display: flex;
  justify-content: center;
  gap: .28em;
}

.uvq08-kbd .k {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  position: relative;
  display: grid;
  place-items: center;
  width: 1.65em;
  height: 2.3em;
  border-radius: .35em;
  font-size: 1em;
  font-weight: 500;
  color: #fff;
  background: #6b6b70;
  box-shadow: 0 1px 0 rgba(0,0,0,.6);
  transition: background calc(0.1s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq08-kbd .bk {
  width: 2.6em;
  margin-left: .4em;
  background: #48484c;
}

.uvq08-kbd .sp {
  width: 11em;
  font-size: .8em;
  height: 2.9em;
  color: #e5e5ea;
}

.uvq08-kbd .k:active {
  background: #8e8e93;
}

.uvq08-kbd .k:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 2px;
}

.uvq08-kbd .lt::before,.uvq08-kbd .lt::after {
  position: absolute;
  left: 50%;
  z-index: 2;
  background: var(--c2);
  pointer-events: none;
  opacity: 0;
  transform-origin: 50% 100%;
  transition: opacity calc(0.08s / var(--k)) cubic-bezier(.25,.1,.25,1),transform calc(0.15s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uvq08-kbd .lt::before {
  content: attr(data-k);
  bottom: calc(100% + .05em);
  display: grid;
  place-items: center;
  width: 1.6em;
  height: 1.6em;
  translate: -50% 0;
  border-radius: .3em .3em .25em .25em;
  font-size: 1.6em;
  font-weight: 400;
  box-shadow: 0 .1em .3em rgba(0,0,0,.4);
  transform: scale(.5);
}

.uvq08-kbd .lt::after {
  content: "";
  bottom: 0;
  width: 100%;
  height: calc(100% + .2em);
  translate: -50% 0;
  border-radius: 0 0 .35em .35em;
  transform: scaleY(.8);
}

.uvq08-kbd .lt:is(:hover,:focus-visible,.on,.pk)::before,.uvq08-kbd .lt:is(:hover,:focus-visible,.on,.pk)::after {
  opacity: 1;
  transform: none;
}

@keyframes uvq08-kbd-c {
  50% {
    opacity: 0;
  }
}

@media (prefers-reduced-motion:reduce) {
  .uvq08-kbd,.uvq08-kbd *,.uvq08-kbd *::before,.uvq08-kbd *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

