document.querySelectorAll(".uvq08-kbd").forEach(el => {
  const unpk=()=>{el.classList.remove("pk");el.querySelectorAll(".pk").forEach(x=>x.classList.remove("pk"))};el.addEventListener("pointerover",unpk,{once:true});el.addEventListener("focusin",unpk,{once:true});const ks=[...el.querySelectorAll(".k")],tx=el.querySelector(".tx"),kb=el.querySelector(".kb"),rows=[...el.querySelectorAll(".rw")].map(r=>[...r.querySelectorAll(".k")]),tm=new Map();let cur=ks.find(k=>k.tabIndex===0)||ks[0];
const type=k=>{const c=k.dataset.k;let s=tx.textContent;s=c==="⌫"?s.slice(0,-1):(s+c.toLowerCase()).slice(-22);tx.textContent=s;k.classList.add("on");clearTimeout(tm.get(k));tm.set(k,setTimeout(()=>k.classList.remove("on"),220))};
const go=k=>{if(!k)return;cur.tabIndex=-1;cur=k;k.tabIndex=0;k.focus()};
ks.forEach(k=>{k.addEventListener("click",()=>type(k));k.addEventListener("focus",()=>{cur.tabIndex=-1;cur=k;k.tabIndex=0})});
kb.addEventListener("keydown",e=>{const ri=rows.findIndex(r=>r.includes(cur)),ci=rows[ri].indexOf(cur);
if(e.key==="ArrowRight")go(rows[ri][ci+1]);else if(e.key==="ArrowLeft")go(rows[ri][ci-1]);
else if(e.key==="ArrowDown"||e.key==="ArrowUp"){const r=rows[ri+(e.key==="ArrowDown"?1:-1)];if(r)go(r[Math.round(ci/Math.max(1,rows[ri].length-1)*(r.length-1))])}
else if(e.key==="Backspace")type(el.querySelector(".bk"));
else if(/^[a-zñ]$/i.test(e.key)&&!e.ctrlKey&&!e.metaKey&&!e.altKey){const m=ks.find(k=>k.dataset.k===e.key.toUpperCase());if(!m)return;go(m);type(m)}
else return;e.preventDefault()});
return()=>tm.forEach(t=>clearTimeout(t))
});

