.uvq08-bpr {
  --c1: #0a4b8c;
  --c2: #ffd166;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq08-bpr {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  position: relative;
  width: 18em;
  height: 13em;
  border-radius: .5em;
  color: #fff;
  background: linear-gradient(rgba(255,255,255,.14) 1px,transparent 1px) -1px -1px/5em 5em,linear-gradient(90deg,rgba(255,255,255,.14) 1px,transparent 1px) -1px -1px/5em 5em,linear-gradient(rgba(255,255,255,.06) 1px,transparent 1px) -1px -1px/1em 1em,linear-gradient(90deg,rgba(255,255,255,.06) 1px,transparent 1px) -1px -1px/1em 1em,var(--c1);
  box-shadow: inset 0 0 0 .3em color-mix(in srgb,var(--c1) 80%,#000),inset 0 0 0 calc(.3em + 1px) rgba(255,255,255,.35),0 1.2em 2em -1em rgba(0,0,0,.55);
}

.uvq08-bpr .dw {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  fill: none;
  stroke: rgba(255,255,255,.88);
  stroke-width: 1.1;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.uvq08-bpr .dw .sp,.uvq08-bpr .dw .lt {
  stroke: rgba(255,255,255,.55);
  stroke-width: .8;
}

.uvq08-bpr .dw .dm {
  stroke: rgba(255,255,255,.6);
  stroke-width: .6;
}

.uvq08-bpr .dw text {
  fill: #fff;
  stroke: none;
  font: 600 5.5px/1 ui-monospace,"SF Mono",Menlo,Consolas,monospace;
}

.uvq08-bpr .ld {
  stroke: var(--c2);
  stroke-width: .9;
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
  transition: stroke-dashoffset calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq08-bpr .hs {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  position: absolute;
  z-index: 2;
  width: 1.35em;
  height: 1.35em;
  translate: -50% -50%;
  border-radius: 50%;
  border: 1.5px dashed rgba(255,255,255,.85);
  background: linear-gradient(#fff,#fff) 50%/.55em 1.5px no-repeat,linear-gradient(#fff,#fff) 50%/1.5px .55em no-repeat,color-mix(in srgb,var(--c1) 70%,transparent);
  transition: all calc(0.3s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uvq08-bpr .hs:focus-visible {
  outline: 2px solid var(--c2);
  outline-offset: 3px;
}

.uvq08-bpr .hs:is(:hover,:focus-visible,.pk) {
  border: 1.5px solid var(--c2);
  rotate: 45deg;
  scale: 1.15;
  background: linear-gradient(var(--c2),var(--c2)) 50%/.55em 1.5px no-repeat,linear-gradient(var(--c2),var(--c2)) 50%/1.5px .55em no-repeat,color-mix(in srgb,var(--c2) 22%,var(--c1));
}

.uvq08-bpr .co {
  position: absolute;
  z-index: 1;
  display: grid;
  gap: .1em;
  padding: .35em .5em;
  border: 1px solid var(--c2);
  font: 500 .6em/1.35 ui-monospace,"SF Mono",Menlo,Consolas,monospace;
  white-space: nowrap;
  background: color-mix(in srgb,var(--c1) 88%,#000);
