.uvq08-hm .hd span {
  font-size: .72em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uvq08-hm .gd {
  position: relative;
  display: grid;
  grid-template-rows: repeat(7,1em);
  grid-auto-flow: column;
  grid-auto-columns: 1em;
  gap: .24em;
}

.uvq08-hm .gd button {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  border-radius: .22em;
  transition: transform calc(0.2s / var(--k)) cubic-bezier(.34,1.56,.64,1),box-shadow calc(0.15s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq08-hm :is(.gd button,.lg i).v0 {
  background: color-mix(in srgb,var(--fg) 8%,transparent);
}

.uvq08-hm :is(.gd button,.lg i).v1 {
  background: color-mix(in srgb,var(--c1) 28%,transparent);
}

.uvq08-hm :is(.gd button,.lg i).v2 {
  background: color-mix(in srgb,var(--c1) 52%,transparent);
}

.uvq08-hm :is(.gd button,.lg i).v3 {
  background: color-mix(in srgb,var(--c1) 78%,transparent);
