.uvq08-hm :is(.gd button,.lg i).v4 {
  background: color-mix(in srgb,var(--c1) 85%,#000);
}

.uvq08-hm .gd button:hover {
  transform: scale(1.15);
}

.uvq08-hm .gd button.on {
  transform: scale(1.25);
  box-shadow: 0 0 0 2px var(--bg),0 0 0 3.5px var(--fg);
}

.uvq08-hm .gd button:focus-visible {
  outline: 0;
