.uvq08-sky {
  --c1: #8fb8ff;
  --c2: #0b1430;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq08-sky {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
}

.uvq08-sky .ch {
  position: relative;
  width: 17em;
  height: 13em;
  border-radius: 1.2em;
  background: linear-gradient(rgba(170,190,255,.06) 1px,transparent 1px) 0 0/100% 2.6em,linear-gradient(90deg,rgba(170,190,255,.06) 1px,transparent 1px) 0 0/2.6em 100%,radial-gradient(120% 90% at 50% 40%,color-mix(in srgb,var(--c2) 60%,#3b4c8f),var(--c2) 70%);
  box-shadow: inset 0 0 0 1px rgba(170,190,255,.12),0 1.2em 2em -1em rgba(0,0,0,.6);
}

.uvq08-sky .ln {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: visible;
}

.uvq08-sky .ln line {
  stroke: rgba(180,200,255,.28);
  stroke-width: 1;
  vector-effect: non-scaling-stroke;
  transition: stroke calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1),stroke-width calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq08-sky .bg {
  position: absolute;
  width: var(--d);
  height: var(--d);
  border-radius: 50%;
  background: #fff;
  opacity: var(--o);
}

.uvq08-sky .nb {
  position: absolute;
  left: 46%;
  top: 66%;
  width: 2.6em;
  height: 2em;
  translate: -50% -50%;
  border-radius: 50%;
  background: radial-gradient(closest-side,rgba(255,140,190,.42),rgba(140,120,255,.14) 60%,transparent);
  filter: blur(2px);
}

.uvq08-sky .st {
  font: inherit;
  color: inherit;
