  animation: uvq08-sky-tw calc(3s / var(--k)) ease-in-out infinite;
  animation-delay: calc(var(--i) * -0.7s);
}

.uvq08-sky .st::after {
  content: "";
  position: absolute;
  inset: .15em;
  border-radius: 50%;
  border: 1px solid var(--c1);
  opacity: 0;
  transform: scale(.4);
  transition: all calc(0.3s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uvq08-sky .st:active::before {
  transform: scale(.8);
}

.uvq08-sky .st:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 2px;
}

.uvq08-sky .st:is(:hover,:focus-visible,.pk) {
  z-index: 4;
}

.uvq08-sky .st:is(:hover,:focus-visible,.pk)::after {
  opacity: 1;
  transform: none;
}

.uvq08-sky .tt {
  position: absolute;
  display: grid;
  gap: .2em;
  width: max-content;
  padding: .55em .75em;
