  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transform: translateY(.3em);
  transition: all calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq08-sky .up .tt {
  bottom: calc(100% + .2em);
}

.uvq08-sky .dn .tt {
  top: calc(100% + .2em);
  transform: translateY(-.3em);
}

.uvq08-sky .hc .tt {
  left: 50%;
  translate: -50% 0;
}

.uvq08-sky .hl .tt {
  left: 0;
}

.uvq08-sky .hr .tt {
  right: 0;
}

.uvq08-sky .tt b {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: .8em;
  font-size: 1.15em;
}

.uvq08-sky .tt b i {
  padding: .1em .4em;
  border-radius: .3em;
  font-size: .68em;
  font-style: normal;
  color: #0b1430;
  background: var(--c);
}

.uvq08-sky .r {
  display: flex;
  justify-content: space-between;
  gap: 1.2em;
  font-variant-numeric: tabular-nums;
}

.uvq08-sky .r em {
  font-style: normal;
  opacity: .65;
}

.uvq08-sky .st:is(:hover,:focus-visible,.pk) .tt {
  opacity: 1;
  visibility: visible;
  transform: none;
}

.uvq08-sky:has(.s0:is(:hover,:focus-visible,.pk)) .a0,.uvq08-sky:has(.s1:is(:hover,:focus-visible,.pk)) .a1,.uvq08-sky:has(.s2:is(:hover,:focus-visible,.pk)) .a2,.uvq08-sky:has(.s3:is(:hover,:focus-visible,.pk)) .a3,.uvq08-sky:has(.s4:is(:hover,:focus-visible,.pk)) .a4,.uvq08-sky:has(.s5:is(:hover,:focus-visible,.pk)) .a5,.uvq08-sky:has(.s6:is(:hover,:focus-visible,.pk)) .a6 {
  stroke: var(--c1);
  stroke-width: 1.8;
}

.uvq08-sky .tl {
  position: absolute;
