  bottom: .8em;
  display: grid;
  color: #cfd9ff;
  pointer-events: none;
}

.uvq08-sky .tl b {
  font: italic 600 1.15em/1.2 Georgia,"Times New Roman",serif;
  letter-spacing: .04em;
}

.uvq08-sky .tl span {
  font-size: .58em;
  letter-spacing: .1em;
  text-transform: uppercase;
  opacity: .65;
}

@keyframes uvq08-sky-tw {
  50% {
    opacity: .75;
    transform: scale(.86);
  }
}

@media (prefers-reduced-motion:reduce) {
  .uvq08-sky,.uvq08-sky *,.uvq08-sky *::before,.uvq08-sky *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

