css:
.uvq08-lgd {
  --c1: #c2410c;
  --c2: #f3ecd9;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq08-lgd {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  width: 17.5em;
  padding-bottom: 3.8em;
}

.uvq08-lgd .mp {
  position: relative;
  height: 10em;
  border-radius: 1em;
  overflow: hidden;
  background: radial-gradient(30% 26% at 70% 72%,rgba(80,150,90,.2),transparent 70%),radial-gradient(24% 30% at 15% 60%,rgba(80,150,90,.18),transparent 70%),repeating-radial-gradient(circle at 42% 28%,transparent 0 1.3em,rgba(150,110,60,.28) 1.3em calc(1.3em + 1px)),repeating-radial-gradient(circle at 82% 76%,transparent 0 1.1em,rgba(150,110,60,.22) 1.1em calc(1.1em + 1px)),var(--c2);
  box-shadow: inset 0 0 0 1px rgba(120,90,40,.25),0 1em 1.8em -1em rgba(0,0,0,.45);
}

.uvq08-lgd .mp>svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  fill: none;
}

.uvq08-lgd .rv {
  stroke: #5b9bd5;
  stroke-width: 3;
  vector-effect: non-scaling-stroke;
  stroke-linecap: round;
}

.uvq08-lgd .tr {
  stroke: var(--c1);
  stroke-width: 2;
  stroke-dasharray: 5 4;
  vector-effect: non-scaling-stroke;
  stroke-linecap: round;
}

.uvq08-lgd .sy {
  position: absolute;
  display: grid;
  place-items: center;
  width: 1.55em;
  height: 1.55em;
  translate: -50% -50%;
  border-radius: 50%;
  color: var(--k);
  background: #fffdf6;
  box-shadow: 0 0 0 1.5px var(--k),0 .2em .3em rgba(0,0,0,.25);
  transition: opacity calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1),filter calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1),transform calc(0.35s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uvq08-lgd .sy svg {
  width: 1em;
  height: 1em;
}

.uvq08-lgd .sy::after {
  content: "";
  position: absolute;
  inset: -.15em;
  border-radius: 50%;
  border: 2px solid var(--k);
  opacity: 0;
}

.uvq08-lgd:has(.lg .wr:is(:hover,:focus-within,.pk)) .sy {
  opacity: .3;
  filter: grayscale(1);
}

.uvq08-lgd:has(.lg0:is(:hover,:focus-within,.pk)) .k0 {
  opacity: 1;
  filter: none;
  transform: scale(1.3);
  z-index: 2;
}

.uvq08-lgd:has(.lg0:is(:hover,:focus-within,.pk)) .k0::after {
  animation: uvq08-lgd-p calc(1.4s / var(--k)) ease-out infinite;
}

.uvq08-lgd:has(.lg1:is(:hover,:focus-within,.pk)) .k1 {
  opacity: 1;
  filter: none;
  transform: scale(1.3);
  z-index: 2;
}

.uvq08-lgd:has(.lg1:is(:hover,:focus-within,.pk)) .k1::after {
  animation: uvq08-lgd-p calc(1.4s / var(--k)) ease-out infinite;
}

.uvq08-lgd:has(.lg2:is(:hover,:focus-within,.pk)) .k2 {
  opacity: 1;
  filter: none;
  transform: scale(1.3);
  z-index: 2;
}

.uvq08-lgd:has(.lg2:is(:hover,:focus-within,.pk)) .k2::after {
  animation: uvq08-lgd-p calc(1.4s / var(--k)) ease-out infinite;
}

.uvq08-lgd:has(.lg3:is(:hover,:focus-within,.pk)) .k3 {
  opacity: 1;
  filter: none;
  transform: scale(1.3);
  z-index: 2;
}

.uvq08-lgd:has(.lg3:is(:hover,:focus-within,.pk)) .k3::after {
  animation: uvq08-lgd-p calc(1.4s / var(--k)) ease-out infinite;
}

.uvq08-lgd .lg {
  display: grid;
  grid-template-columns: repeat(4,1fr);
  gap: .35em;
  margin-top: .6em;
}

.uvq08-lgd .wr {
  position: relative;
  min-width: 0;
}

.uvq08-lgd button {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: .25em;
  width: 100%;
  padding: .5em .2em .45em;
  border-radius: .9em;
  font-size: .72em;
  white-space: nowrap;
  font-weight: 650;
  background: color-mix(in srgb,var(--fg) 6%,transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb,var(--fg) 10%,transparent);
  transition: all calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq08-lgd button svg {
  flex: none;
  width: 1.35em;
  height: 1.35em;
  color: var(--k);
}

.uvq08-lgd button:hover,.uvq08-lgd .wr.pk button {
  background: color-mix(in srgb,var(--k) 14%,transparent);
  box-shadow: inset 0 0 0 1.5px var(--k);
}

.uvq08-lgd button:active {
  transform: scale(.95);
}

.uvq08-lgd button:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uvq08-lgd .tt {
  position: absolute;
  left: 50%;
  top: calc(100% + .7em);
  z-index: 3;
  display: grid;
  gap: .1em;
  width: max-content;
  padding: .5em .75em;
  border-radius: .7em;
  font-size: .74em;
  line-height: 1.35;
  color: var(--bg);
  background: var(--fg);
  box-shadow: 0 .8em 1.6em -.6em rgba(0,0,0,.45);
  transform: translate(-50%,-.3em);
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: all calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq08-lgd .tt::after {
  content: "";
  position: absolute;
  left: 50%;
  bottom: 100%;
  width: .7em;
  height: .7em;
  background: var(--fg);
  transform: translate(-50%,55%) rotate(45deg);
  border-radius: .15em 0 0 0;
}

.uvq08-lgd .tt span {
  opacity: .7;
}

.uvq08-lgd .wr:first-child .tt {
  left: 0;
  transform: translateY(-.3em);
}

.uvq08-lgd .wr:first-child .tt::after {
  left: 1.8em;
}

.uvq08-lgd .wr:last-child .tt {
  left: auto;
  right: 0;
  transform: translateY(-.3em);
}

.uvq08-lgd .wr:last-child .tt::after {
  left: auto;
  right: 1.6em;
  transform: translate(50%,55%) rotate(45deg);
}

.uvq08-lgd .wr:is(:hover,:focus-within,.pk) .tt {
  transform: translate(-50%,0);
  opacity: 1;
  visibility: visible;
}

.uvq08-lgd .wr:is(:first-child,:last-child):is(:hover,:focus-within,.pk) .tt {
  transform: none;
}

@keyframes uvq08-lgd-p {
  0% {
    transform: scale(.9);
    opacity: .9;
  }
  100% {
    transform: scale(2.1);
    opacity: 0;
  }
}

@media (prefers-reduced-motion:reduce) {
  .uvq08-lgd,.uvq08-lgd *,.uvq08-lgd *::before,.uvq08-lgd *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

