.uvq08-elv {
  --c1: #0f766e;
  --c2: #99f6e4;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq08-elv {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  width: 18em;
  padding: 1em 1.1em .8em;
  border-radius: 1.2em;
  background: color-mix(in srgb,var(--fg) 3%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 8%,transparent),0 24px 48px -30px rgba(0,0,0,.45);
}

.uvq08-elv .hd {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1em;
  margin-bottom: .7em;
}

.uvq08-elv .tx {
  display: grid;
  gap: .15em;
}

.uvq08-elv .tx span {
  font-size: .72em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
  font-variant-numeric: tabular-nums;
}

.uvq08-elv .rt {
  flex: none;
  width: 3.6em;
  height: 3.6em;
  border-radius: .7em;
  background: repeating-radial-gradient(circle at 70% 30%,transparent 0 .45em,color-mix(in srgb,var(--fg) 10%,transparent) .45em calc(.45em + 1px)),color-mix(in srgb,var(--c2) 25%,transparent);
  overflow: visible;
}

.uvq08-elv .rt polyline {
  fill: none;
  stroke: var(--c1);
  stroke-width: 2.2;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: 4 3;
}

.uvq08-elv .rt .a {
  fill: var(--bg);
  stroke: var(--c1);
  stroke-width: 1.6;
}

.uvq08-elv .rt .b {
  fill: var(--c1);
}

.uvq08-elv .rt .me {
  fill: #f97316;
  stroke: var(--bg);
  stroke-width: 1.5;
  transition: cx calc(0.15s / var(--k)) cubic-bezier(.25,.1,.25,1),cy calc(0.15s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq08-elv .pf {
  position: relative;
  height: 6em;
  margin-top: 2.6em;
  border-radius: .5em;
  outline: 0;
  cursor: crosshair;
  touch-action: none;
}

.uvq08-elv .pf:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uvq08-elv .pf svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.uvq08-elv .ar {
  fill: color-mix(in srgb,var(--c1) 18%,transparent);
}

.uvq08-elv .li {
  fill: none;
  stroke: var(--c1);
  stroke-width: 2;
  vector-effect: non-scaling-stroke;
  stroke-linejoin: round;
}

.uvq08-elv .vl,.uvq08-elv .dt,.uvq08-elv .tt {
  position: absolute;
  left: calc(var(--p) * 100%);
  opacity: 0;
  pointer-events: none;
  transition: opacity calc(0.15s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq08-elv .vl {
  top: calc(var(--y) * 100%);
  bottom: 0;
  width: 0;
  border-left: 1.5px dashed color-mix(in srgb,var(--fg) 45%,transparent);
}

.uvq08-elv .dt {
  top: calc(var(--y) * 100%);
  width: .7em;
  height: .7em;
  translate: -50% -50%;
  border-radius: 50%;
  background: #f97316;
  box-shadow: 0 0 0 2px var(--bg);
}

.uvq08-elv .tt {
  top: calc(var(--y) * 100%);
  z-index: 3;
  display: grid;
  grid-template-columns: auto auto;
  gap: .1em .6em;
  padding: .45em .65em;
  border-radius: .6em;
  font-size: .74em;
  line-height: 1.3;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
  color: var(--bg);
  background: var(--fg);
  box-shadow: 0 .8em 1.6em -.6em rgba(0,0,0,.45);
  translate: calc(var(--p) * -100%) calc(-100% - 1.2em);
}

.uvq08-elv .tt b {
  grid-column: 1/-1;
  font-size: 1.15em;
}

.uvq08-elv .km {
  opacity: .7;
}

.uvq08-elv .sl {
  font-weight: 800;
}

.uvq08-elv .lo .sl {
  color: #22c55e;
}

.uvq08-elv .md .sl {
  color: #f59e0b;
}

.uvq08-elv .hi .sl {
  color: #ef4444;
}

.uvq08-elv .dn .sl {
  color: #38bdf8;
}

.uvq08-elv .pf:is(:hover,:focus-visible,.pk,.on) :is(.vl,.dt,.tt) {
  opacity: 1;
}

.uvq08-elv .ax {
  display: flex;
  justify-content: space-between;
  margin-top: .35em;
  font-size: .65em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

