pf.addEventListener("pointermove",e=>{pf.classList.add("on");at(e)});pf.addEventListener("pointerdown",e=>{pf.classList.add("on");at(e)});pf.addEventListener("pointerleave",()=>pf.classList.remove("on"));
pf.addEventListener("keydown",e=>{const d={ArrowRight:1,ArrowUp:1,ArrowLeft:-1,ArrowDown:-1,PageUp:5,PageDown:-5}[e.key];if(e.key==="Home")set(0);else if(e.key==="End")set(n-1);else if(d)set(cur+d);else return;e.preventDefault()});
set(cur)
