css:
.uvq08-sea {
  --c1: #0e7490;
  --c2: #cfe8f3;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq08-sea {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
}

.uvq08-sea .cht {
  position: relative;
  width: 18em;
  height: 12.6em;
  border-radius: .6em;
  background: radial-gradient(60% 70% at 100% 40%,color-mix(in srgb,var(--c2) 40%,#fff),transparent 70%),var(--c2);
  box-shadow: inset 0 0 0 .3em #fffef8,inset 0 0 0 calc(.3em + 1px) #1d3557,0 1.2em 2em -1em rgba(0,0,0,.5);
}

.uvq08-sea svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.uvq08-sea .c10,.uvq08-sea .c5 {
  fill: none;
  stroke: #1d3557;
  stroke-width: .35;
  stroke-dasharray: 1.5 1;
  opacity: .55;
}

.uvq08-sea .c5 {
  stroke-dasharray: .6 .8;
}

.uvq08-sea .ld {
  fill: #f1e2b6;
  stroke: #6b5b3a;
  stroke-width: .5;
}

.uvq08-sea .tk {
  fill: none;
  stroke: #1d3557;
  stroke-width: .4;
  stroke-dasharray: 2 1.2;
}

.uvq08-sea text {
  fill: #1d3557;
  font: italic 3.2px/1 Georgia,"Times New Roman",serif;
  opacity: .75;
}

.uvq08-sea .ca {
  position: absolute;
  left: .8em;
  top: .75em;
  display: grid;
  padding: .3em .55em;
  border: 1px solid #1d3557;
  font-family: Georgia,"Times New Roman",serif;
  color: #1d3557;
  background: rgba(255,254,248,.8);
}

.uvq08-sea .ca b {
  font-style: italic;
  font-size: .9em;
}

.uvq08-sea .ca span {
  font-size: .55em;
  letter-spacing: .08em;
  text-transform: uppercase;
}

.uvq08-sea .by {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  position: absolute;
  z-index: 2;
  display: grid;
  place-items: center;
  width: 2.2em;
  height: 2.2em;
  translate: -50% -50%;
  border-radius: 50%;
  transition: background calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq08-sea .by:hover,.uvq08-sea .by.pk {
  background: rgba(255,255,255,.35);
}

.uvq08-sea .by:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uvq08-sea .by:active .sh {
  transform: scale(.88);
}

.uvq08-sea .sh {
  display: block;
  width: .8em;
  height: 1em;
  transition: transform calc(0.2s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uvq08-sea .red .sh {
  border-radius: .15em;
  background: linear-gradient(90deg,#9b1c1c,#e53e3e 45%,#9b1c1c);
  box-shadow: 0 .1em 0 #5a1010;
}

.uvq08-sea .grn .sh {
  clip-path: polygon(50% 0,100% 100%,0 100%);
  background: linear-gradient(90deg,#14532d,#22a35a 45%,#14532d);
}

.uvq08-sea .car .sh {
  width: .7em;
  height: 1.15em;
  border-radius: .1em;
  background: linear-gradient(#111 0 50%,#facc15 50%);
}

.uvq08-sea .lh .sh {
  width: .75em;
  height: 1.2em;
  clip-path: polygon(25% 0,75% 0,100% 100%,0 100%);
  background: linear-gradient(#fff 0 30%,#d62828 30% 50%,#fff 50% 75%,#d62828 75%);
}

.uvq08-sea .lt {
  position: absolute;
  left: 50%;
  top: .05em;
  width: .45em;
  height: .45em;
  translate: -50% 0;
  border-radius: 50%;
  opacity: .15;
  animation: var(--a) var(--t) steps(1,end) infinite;
}

.uvq08-sea .red .lt {
  background: #ff4d4d;
  box-shadow: 0 0 .5em .2em #ff4d4d;
}

.uvq08-sea .grn .lt {
  background: #4ade80;
  box-shadow: 0 0 .5em .2em #4ade80;
}

.uvq08-sea .car .lt {
  background: #fff;
  box-shadow: 0 0 .5em .2em #fff7c2;
}

.uvq08-sea .lh .lt {
  top: -.25em;
  background: #fff7c2;
  box-shadow: 0 0 .8em .35em #ffe08a;
}

.uvq08-sea .f1 {
  --a: uvq08-sea-f1;
}

.uvq08-sea .f2 {
  --a: uvq08-sea-f2;
}

.uvq08-sea .f3 {
  --a: uvq08-sea-f3;
}

.uvq08-sea .q {
  --a: uvq08-sea-q;
}

.uvq08-sea .tt {
  position: absolute;
  z-index: 3;
  display: grid;
  gap: .15em;
  width: max-content;
  max-width: 11em;
  padding: .5em .7em;
  border: 1px solid #1d3557;
  border-radius: .2em;
  font-size: .72em;
  line-height: 1.3;
  text-align: left;
  color: #1d3557;
  background: #fffef8;
  box-shadow: .3em .3em 0 rgba(29,53,87,.18);
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: all calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq08-sea .tt b {
  font: italic 700 1.1em/1.2 Georgia,"Times New Roman",serif;
}

.uvq08-sea .tt code {
  justify-self: start;
  margin-top: .15em;
  padding: .1em .4em;
  border-radius: .2em;
  font: 700 .92em/1.3 ui-monospace,"SF Mono",Menlo,Consolas,monospace;
  color: #fff;
  background: #1d3557;
}

.uvq08-sea .up .tt {
  bottom: calc(100% + .1em);
}

.uvq08-sea .dn .tt {
  top: calc(100% + .1em);
}

.uvq08-sea .hc .tt {
  left: 50%;
  translate: -50% 0;
}

.uvq08-sea .hr .tt {
  right: 0;
}

.uvq08-sea .by:is(:hover,:focus-visible,.pk) {
  z-index: 4;
}

.uvq08-sea .by:is(:hover,:focus-visible,.pk) .tt {
  opacity: 1;
  visibility: visible;
}

.uvq08-sea .by:is(:hover,:focus-visible,.pk) .lt {
  scale: 1.5;
}

@keyframes uvq08-sea-f1 {
  0% {
    opacity: 1;
  }
  8% {
    opacity: .15;
  }
}

@keyframes uvq08-sea-f2 {
  0% {
    opacity: 1;
  }
  6% {
    opacity: .15;
  }
  12% {
    opacity: 1;
  }
  18% {
    opacity: .15;
  }
}

@keyframes uvq08-sea-f3 {
  0% {
    opacity: 1;
  }
  4% {
    opacity: .15;
  }
  9% {
    opacity: 1;
  }
  13% {
    opacity: .15;
  }
  18% {
    opacity: 1;
  }
  22% {
    opacity: .15;
  }
}

@keyframes uvq08-sea-q {
  0% {
    opacity: 1;
  }
  50% {
    opacity: .15;
  }
}

@media (prefers-reduced-motion:reduce) {
  .uvq08-sea,.uvq08-sea *,.uvq08-sea *::before,.uvq08-sea *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

