css:
.uvq08-tz {
  --c1: #ffcf5c;
  --c2: #123a5e;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq08-tz {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  width: 18em;
  padding-top: 3.4em;
}

.uvq08-tz .hd {
  margin: .55em 0 0;
  font-size: .78em;
  font-weight: 700;
  text-align: center;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uvq08-tz .wm {
  position: relative;
  height: 9em;
  border-radius: .8em;
  background: var(--c2);
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.08),0 1.2em 2em -1em rgba(0,0,0,.55);
}

.uvq08-tz .wm>svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  border-radius: .8em;
}

.uvq08-tz .gr {
  fill: none;
  stroke: rgba(255,255,255,.08);
  stroke-width: 1;
  vector-effect: non-scaling-stroke;
}

.uvq08-tz polygon {
  fill: #4f8f78;
  stroke: #3a6f5d;
  stroke-width: 1;
  stroke-linejoin: round;
  vector-effect: non-scaling-stroke;
}

.uvq08-tz .nt {
  fill: rgba(2,6,23,.55);
  filter: blur(2px);
  transition: d calc(1s / var(--k)) linear;
}

.uvq08-tz .sun {
  position: absolute;
  width: 1.5em;
  height: 1.5em;
  translate: -50% -50%;
  border-radius: 50%;
  background: radial-gradient(circle,#fff6d1 0 22%,rgba(255,214,102,.5) 24% 30%,transparent 32%),repeating-conic-gradient(rgba(255,214,102,.85) 0 8deg,transparent 8deg 30deg);
  -webkit-mask: radial-gradient(circle,#000 0 62%,transparent 66%);
  mask: radial-gradient(circle,#000 0 62%,transparent 66%);
  pointer-events: none;
  animation: uvq08-tz-s 20s linear infinite;
}

@keyframes uvq08-tz-s {
  to {
    rotate: 360deg;
  }
}

.uvq08-tz .ct {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  position: absolute;
  z-index: 2;
  display: grid;
  place-items: center;
  width: 1.7em;
  height: 1.7em;
  translate: -50% -50%;
  border-radius: 50%;
}

.uvq08-tz .ct::before {
  content: "";
  width: .6em;
  height: .6em;
  border-radius: 50%;
  background: var(--c1);
  box-shadow: 0 0 0 2px rgba(0,0,0,.35),0 0 .5em var(--c1);
  transition: transform calc(0.3s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uvq08-tz .ct:hover::before,.uvq08-tz .ct.pk::before {
  transform: scale(1.4);
}

.uvq08-tz .ct:active::before {
  transform: scale(.8);
}

.uvq08-tz .ct:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 1px;
}

.uvq08-tz .tt {
  position: absolute;
  bottom: calc(100% + .25em);
  z-index: 3;
  display: grid;
  grid-template-columns: auto auto;
  align-items: center;
  gap: 0 .7em;
  width: max-content;
  padding: .45em .7em;
  border-radius: .7em;
  font-size: .74em;
  line-height: 1.25;
  text-align: left;
  color: var(--bg);
  background: var(--fg);
  box-shadow: 0 .8em 1.6em -.6em rgba(0,0,0,.45);
  transform: translateY(.3em);
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: all calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq08-tz .hc .tt {
  left: 50%;
  translate: -50% 0;
}

.uvq08-tz .hr .tt {
  right: 0;
}

.uvq08-tz .tt b {
  grid-column: 1/-1;
  font-size: .85em;
  opacity: .75;
}

.uvq08-tz .tm {
  font-size: 1.5em;
  font-weight: 750;
  font-variant-numeric: tabular-nums;
  letter-spacing: -.02em;
}

.uvq08-tz .of {
  display: grid;
  justify-items: center;
  gap: .1em;
  font-size: .8em;
  font-weight: 650;
}

.uvq08-tz .of svg {
  width: 1.3em;
  height: 1.3em;
  fill: none;
  stroke: #f59e0b;
  stroke-width: 2;
  stroke-linecap: round;
}

.uvq08-tz .of .n {
  display: none;
  fill: #a5b4fc;
  stroke: none;
}

.uvq08-tz .nite .of .d {
  display: none;
}

.uvq08-tz .nite .of .n {
  display: block;
}

.uvq08-tz .ct:is(:hover,:focus-visible,.pk) {
  z-index: 4;
}

.uvq08-tz .ct:is(:hover,:focus-visible,.pk) .tt {
  transform: none;
  opacity: 1;
  visibility: visible;
}

@media (prefers-reduced-motion:reduce) {
  .uvq08-tz,.uvq08-tz *,.uvq08-tz *::before,.uvq08-tz *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

