document.querySelectorAll(".uvq08-tz").forEach(el => {
  const unpk=()=>{el.classList.remove("pk");el.querySelectorAll(".pk").forEach(x=>x.classList.remove("pk"))};el.addEventListener("pointerover",unpk,{once:true});el.addEventListener("focusin",unpk,{once:true});const nt=el.querySelector(".nt"),sun=el.querySelector(".sun"),lang=document.documentElement.lang||undefined,R=Math.PI/180;
const calc=d=>{const n=Math.floor((d.getTime()-Date.UTC(d.getUTCFullYear(),0,0))/864e5),dec=-23.44*Math.cos(2*Math.PI/365*(n+10))*R,ls=(12-d.getUTCHours()-d.getUTCMinutes()/60)*15,pts=[];for(let x=0;x<=360;x+=6)pts.push(x+","+(90-Math.atan(-Math.cos((x-180-ls)*R)/Math.tan(dec))/R).toFixed(1));const e=dec<0?0:180;return{p:"M0,"+e+" L"+pts.join(" L")+" L360,"+e+" Z",ls,dec}};
const upd=()=>{const d=new Date(),o=calc(d);nt.setAttribute("d",o.p);sun.style.left=(((o.ls+180)%360+360)%360/3.6)+"%";sun.style.top=((90-o.dec/R)/1.8)+"%";
el.querySelectorAll(".ct").forEach(c=>{const tz=c.dataset.tz,lat=+c.dataset.lat*R,lon=+c.dataset.lon;try{c.querySelector(".tm").textContent=d.toLocaleTimeString(lang,{timeZone:tz,hour:"2-digit",minute:"2-digit"});const p=new Intl.DateTimeFormat(lang,{timeZone:tz,timeZoneName:"shortOffset"}).formatToParts(d).find(x=>x.type==="timeZoneName");if(p)c.querySelector(".ofs").textContent=p.value}catch(e){}
const h=Math.sin(lat)*Math.sin(o.dec)+Math.cos(lat)*Math.cos(o.dec)*Math.cos((lon-o.ls)*R);c.classList.toggle("nite",h<0)})};
upd();const iv=setInterval(upd,30000);return()=>clearInterval(iv)
});

